let frontmatter = {
    "title": "Reasoning Routing"
};
let structuredData = {
    "contents": [
        {
            "heading": "reasoning-routing",
            "content": "Reasoning routing rules extend the existing model and combo routing. When no active rule matches,\r\nthe existing thinking, suffix, connection-default, and provider-translation behavior remains\r\nunchanged."
        },
        {
            "heading": "management",
            "content": "Rule management is available under **Settings → Global Routing**. The API-key editor provides the\r\nsame management UI filtered to the selected key."
        },
        {
            "heading": "management",
            "content": "The management API is exposed by these routes:"
        },
        {
            "heading": "management",
            "content": "`GET` and `POST` at `/api/settings/reasoning-routing-rules`"
        },
        {
            "heading": "management",
            "content": "`GET`, `PATCH`, and `DELETE` at `/api/settings/reasoning-routing-rules/[id]`"
        },
        {
            "heading": "management",
            "content": "`POST` at `/api/settings/reasoning-routing-rules/simulate`"
        },
        {
            "heading": "management",
            "content": "All routes use `requireManagementAuth`. Inputs are validated with the schemas in\r\n`src/shared/validation/schemas/reasoningRouting.ts`. The simulator never makes an upstream call."
        },
        {
            "heading": "rule-resolution",
            "content": "The early evaluation selects exactly one rule. Scopes are checked in this order:"
        },
        {
            "heading": "rule-resolution",
            "content": "`apiKey`"
        },
        {
            "heading": "rule-resolution",
            "content": "`combo`"
        },
        {
            "heading": "rule-resolution",
            "content": "`model`"
        },
        {
            "heading": "rule-resolution",
            "content": "`global`"
        },
        {
            "heading": "rule-resolution",
            "content": "Within a scope, higher `priority` wins first, followed by an exact model match over a glob pattern,\r\nthen stable `createdAt` and `id` ordering. `requestTags` are read exclusively from `metadata.tags`\r\nand support `any` or `all` matching."
        },
        {
            "heading": "rule-resolution",
            "content": "A `connection` rule is evaluated only when no early rule won and a concrete provider connection has\r\nalready been selected. It may change effort and budget only."
        },
        {
            "heading": "effort-and-budget",
            "content": "`sourceEffort` accepts `any`, `missing`, `none`, `low`, `medium`, `high`, `xhigh`, `max`, and\r\n`ultra`. `missing` means that the request contains neither a discrete effort nor a thinking toggle\r\nor thinking budget. A budget-only signal is therefore matched only by `any`."
        },
        {
            "heading": "effort-and-budget",
            "content": "`effortMode` has three variants:"
        },
        {
            "heading": "effort-and-budget",
            "content": "`inherit` keeps the client effort while still allowing the model or combo to change."
        },
        {
            "heading": "effort-and-budget",
            "content": "`default` sets `targetEffort` only when no explicit reasoning signal is present."
        },
        {
            "heading": "effort-and-budget",
            "content": "`force` replaces the discrete effort with `targetEffort`."
        },
        {
            "heading": "effort-and-budget",
            "content": "Independently, `budgetAction` can be `preserve`, `remove`, or `set`. `force` with `none` removes\r\nall recognized effort and budget fields. `none` together with `set` is invalid."
        },
        {
            "heading": "effort-and-budget",
            "content": "Requests targeting known-incompatible models are rejected before the upstream call. For combo\r\ntargets, incompatible entries are removed; if none remain, the request returns status `400`.\r\nUnknown capability data produces a warning and leaves the rule active."
        },
        {
            "heading": "security-and-transports",
            "content": "The source and target model, or source and target combo, remain subject to the existing API-key\r\npolicy. A reasoning rule never expands model, combo, or quota permissions."
        },
        {
            "heading": "security-and-transports",
            "content": "The engine is integrated into Chat Completions, Responses, Anthropic Messages, and the internal\r\nCodex WebSocket path. The WebSocket path accepts Codex target models only; combo targets cannot be\r\nexecuted there. The rule decision is stored in the existing route trace without secrets."
        },
        {
            "heading": "persistence",
            "content": "The migration `src/lib/db/migrations/126_reasoning_routing_rules.sql` creates the\r\n`reasoning_routing_rules` table. Rules reference stored API keys, combos, and provider connections.\r\nDeletes clean up related rules. The database access layer in\r\n`src/lib/db/reasoningRoutingRules.ts` maintains an invalidatable cache for the request path."
        },
        {
            "heading": "persistence",
            "content": "Rules are included in SQLite backups, the full database export, and the config-sync bundle.\r\n`reconcileReasoningRulesForSync` disables imported rules with missing references and reports those\r\nconflicts."
        }
    ],
    "headings": [
        {
            "id": "reasoning-routing",
            "content": "Reasoning Routing"
        },
        {
            "id": "management",
            "content": "Management"
        },
        {
            "id": "rule-resolution",
            "content": "Rule Resolution"
        },
        {
            "id": "effort-and-budget",
            "content": "Effort and Budget"
        },
        {
            "id": "security-and-transports",
            "content": "Security and Transports"
        },
        {
            "id": "persistence",
            "content": "Persistence"
        }
    ]
};
